1	//! scrcpy 4.x 控制协议客户端。
2	//! 消息格式参照 scrcpy 源码 app/src/control_msg.c 的 sc_control_msg_serialize()。
3	
4	use crate::{diag_info, diag_warn};
5	use anyhow::{Context, Result};
6	use std::collections::VecDeque;
7	use std::io::{Read, Write};
8	use std::net::TcpStream;
9	use std::sync::atomic::{AtomicBool, AtomicU32, AtomicU64, AtomicUsize, Ordering};
10	use std::sync::{Arc, Condvar, Mutex};
11	
