35	#[derive(Debug, Clone)]
36	pub enum ControlCmd {
37	    Touch {
38	        action: u8,
39	        pointer_id: u64,
40	        x: u32,
41	        y: u32,
42	    },
43	    Key {
44	        action: u8,
45	        keycode: u32,
46	    },
47	    UhidCreate {
48	        id: u16,
49	        vendor_id: u16,
50	        product_id: u16,
51	        name: String,
52	        report_desc: Vec<u8>,
53	    },
54	    UhidInput {
