63	/// Move 类命令允许的最大排队深度(W1-3)。达到它说明设备端/转发通道已经堵了:
64	/// 位移是绝对坐标语义,"丢旧保新"不改变指针最终位置;而**重放**一长串过期位移
65	/// 才是真的坏事 —— 指针会先沿陈旧路径划过一遍再追上当前位置。
66	const MOVE_BACKLOG_LIMIT: usize = 256;
67	
68	/// 一次 `write_all` 最多拼多少条命令(见写线程里的攒批说明)。
69	/// 64 足够覆盖"一次按下引发的 down+move+滑动插值"这种突发,又不至于让
70	/// 单次写入的字节数失控(触摸 32B、按键 12B 量级 → 一次 write 最多 ~2KB)。
71	const WRITE_BATCH_LIMIT: usize = 64;
72	
73	/// 控制队列的实时快照(诊断面板用)
74	#[derive(Debug, Clone, Copy, Default)]
75	pub struct QueueStats {
76	    pub depth: usize,
77	    pub peak: usize,
78	    pub dropped: u64,
79	}
80	
81	/// 控制命令队列(W1-3):替代原来的无界 `mpsc`。
82	///
83	/// 与 mpsc 的差别只有两点,都是"看得见 + 压得住":
84	/// 1. **深度可见**:发送方随时能读到当前/峰值深度与丢弃计数(诊断面板显示);
85	/// 2. **Move 类丢旧保新**:排队深度达到 `MOVE_BACKLOG_LIMIT` 时,新的
86	///    `ACTION_MOVE` 顶掉**同一触点最旧的那条** —— 每个来源(瞄准/轮盘/宏/
87	///    手柄)有自己的 `pointer_id`,互不干扰,顺序也不乱。
88	///
89	/// 其余命令(按下/抬起/按键/UHID)一条都不丢:它们是边沿语义,丢了就是
90	/// 卡键或丢操作 —— 宁可积压,不可失序。
91	struct CmdQueue {
92	    q: Mutex<VecDeque<ControlCmd>>,
93	    cv: Condvar,
94	    peak: AtomicUsize,
95	    dropped: AtomicU64,
96	    /// 已被写线程取走、但**还没写进 socket** 的命令条数(攒批的本地缓冲)。
97	    ///
98	    /// 攒批把最多 `WRITE_BATCH_LIMIT` 条命令从队列挪进了写线程自己的 `buf`,
99	    /// 那批命令还在途 —— 不算进来的话:①诊断面板的"深度"会在最该看的时候
100	    /// (socket 卡住、写线程堵在 `write_all` 上)少报一整个批次;②"丢旧保新"
101	    /// 的在途上限会从 256 放宽到 256+64,卡顿恢复后多写出几十条过期位移。
102	    /// 只由写线程改(取一条 +1、写完一批 -= n),`push` 在锁内读。
103	    inflight: AtomicUsize,
104	    /// 客户端销毁后置位:消费者"取空 + 已关闭"即退出(等价于 mpsc 的断开)
105	    closed: AtomicBool,
106	}
107	
108	impl CmdQueue {
109	    fn new() -> Arc<Self> {
110	        Arc::new(Self {
111	            q: Mutex::new(VecDeque::new()),
112	            cv: Condvar::new(),
113	            peak: AtomicUsize::new(0),
114	            dropped: AtomicU64::new(0),
115	            inflight: AtomicUsize::new(0),
116	            closed: AtomicBool::new(false),
117	        })
118	    }
119	
120	    fn push(&self, cmd: ControlCmd) {
121	        // 锁中毒不放弃:注入路径不能因为某个持锁线程 panic 就全线卡死
122	        let mut q = self.q.lock().unwrap_or_else(|e| e.into_inner());
123	        let mut dropped_now = None;
124	        let move_pid = match &cmd {
125	            ControlCmd::Touch {
126	                action: ACTION_MOVE,
127	                pointer_id,
128	                ..
129	            } => Some(*pointer_id),
130	            _ => None,
131	        };
132	        // 在途量 = 队列里 + 写线程手里还没落 socket 的那一批(见 `inflight`)
133	        let backlog = q.len() + self.inflight.load(Ordering::Relaxed);
134	        if let Some(pid) = move_pid.filter(|_| backlog >= MOVE_BACKLOG_LIMIT) {
135	            let oldest = q.iter().position(|c| {
136	                matches!(
137	                    c,
138	                    ControlCmd::Touch { action: ACTION_MOVE, pointer_id, .. } if *pointer_id == pid
139	                )
140	            });
141	            if let Some(i) = oldest {
142	                q.remove(i);
143	                dropped_now = Some(self.dropped.fetch_add(1, Ordering::Relaxed) + 1);
144	            }
145	        }
146	        q.push_back(cmd);
147	        // 峰值记"在途量"(队列 + 写线程手里的那批):面板上这两个数就是用户
148	        // 判断"堵在我们这一侧还是设备侧"的依据,不能少算一整个批次。
149	        self.peak.fetch_max(
150	            q.len() + self.inflight.load(Ordering::Relaxed),
151	            Ordering::Relaxed,
152	        );
153	        drop(q);
154	        self.cv.notify_one();
155	        // 日志放在锁外:diag 的写盘不能拖住持锁的注入路径。
156	        // 首次与每 1000 条各记一次,免得持续积压时把日志刷爆。
157	        if let Some(n) = dropped_now.filter(|n| *n == 1 || n % 1000 == 0) {
158	            diag_warn!(
159	                "control",
160	                "控制队列积压(≥{MOVE_BACKLOG_LIMIT}):累计丢弃 {n} 条过期 Move(保新)——设备端或转发通道变慢"
161	            );
162	        }
163	    }
164	
165	    /// 阻塞取一条;`None` = 队列已关闭且取空(客户端已销毁)。
166	    ///
167	    /// 取走即计入 `inflight`(它还没写进 socket),写完由 `written()` 冲销 ——
168	    /// 于是 `depth` 在"取走"这一步不下降(总数不变),只在真正写完后下降。
169	    fn pop(&self) -> Option<ControlCmd> {
170	        let mut q = self.q.lock().unwrap_or_else(|e| e.into_inner());
171	        loop {
172	            if let Some(c) = q.pop_front() {
173	                self.inflight.fetch_add(1, Ordering::Relaxed);
174	                return Some(c);
175	            }
176	            if self.closed.load(Ordering::Relaxed) {
177	                return None;
178	            }
179	            q = self.cv.wait(q).unwrap_or_else(|e| e.into_inner());
180	        }
181	    }
182	
183	    /// 非阻塞取一条(攒批用):拿不到就返回 None,绝不等。
184	    fn try_pop(&self) -> Option<ControlCmd> {
185	        let mut q = self.q.lock().unwrap_or_else(|e| e.into_inner());
186	        let c = q.pop_front();
187	        if c.is_some() {
188	            self.inflight.fetch_add(1, Ordering::Relaxed);
189	        }
190	        c
191	    }
192	
193	    /// 写线程报账:这一批 `n` 条已经离开本地(写完,或写失败被丢弃),
194	    /// 从在途量里冲销。
195	    fn written(&self, n: usize) {
196	        self.inflight.fetch_sub(n, Ordering::Relaxed);
197	    }
198	
199	    /// 客户端销毁:唤醒写线程,让它取空后自行退出
200	    fn close(&self) {
201	        self.closed.store(true, Ordering::Relaxed);
202	        self.cv.notify_all();
203	    }
204	
205	    /// 诊断快照。`depth` **现算**:队列里的 + 写线程手里还没落 socket 的那批
206	    /// (见 `inflight`)—— 攒批之后"队列长度"不再是"还没发出去的条数",而面板上
207	    /// 那个数要回答的正是后者。取一次锁的代价可以忽略(与 `push` 同一把锁,
208	    /// 界面每帧至多问一次)。
209	    fn stats(&self) -> QueueStats {
210	        let queued = self.q.lock().unwrap_or_else(|e| e.into_inner()).len();
211	        QueueStats {
212	            depth: queued + self.inflight.load(Ordering::Relaxed),
213	            peak: self.peak.load(Ordering::Relaxed),
214	            dropped: self.dropped.load(Ordering::Relaxed),
215	        }
216	    }
217	}
218	
219	/// 低延迟注入通道:专用写线程 + 命令队列(深度可见、Move 类丢旧保新,W1-3)
220	pub struct ControlClient {
221	    queue: Arc<CmdQueue>,
222	    connected: Arc<AtomicBool>,
223	    /// 设备屏幕宽(逻辑像素),用于瞄准偏移的边界钳制
224	    pub screen_w: u32,
225	    /// 设备屏幕高
226	    pub screen_h: u32,
227	    /// 写线程**真正用来序列化**的宽高。
228	    ///
229	    /// 为什么要单独一份:`screen_w/h` 是给引擎算坐标用的普通字段,
230	    /// 而写线程在 `move` 走了自己的副本之后再也看不到对它的修改 ——
231	    /// 于是会出现"引擎按新尺寸算坐标、消息里却声明旧尺寸"的不一致。
232	    /// 当前用 control-only 模式(服务端走原始坐标、不校验尺寸)所以无害,
233	    /// 但一旦有人启用视频或 `--new-display`,服务端 `PositionMapper.map()`
234	    /// 会因尺寸不符把**每一条**触摸事件丢弃,且不报任何错。
235	    /// 用原子量让两者始终一致,避免以后踩这个坑。
236	    proto_w: Arc<AtomicU32>,
237	    proto_h: Arc<AtomicU32>,
238	}
239	
240	impl ControlClient {
241	    /// 连接到已转发到本地端口的 scrcpy control socket。
242	    /// 必须读取 server 的 dummy 字节以确认设备侧 socket 真的被接受
243	    /// (adb forward 在本地总是先完成 TCP 握手,设备侧未就绪时随即 EOF)。
244	    pub fn connect(port: u16, screen_w: u32, screen_h: u32) -> Result<Self> {
245	        let mut stream = TcpStream::connect(("127.0.0.1", port))
246	            .context("连接本地转发端口失败(scrcpy-server 是否已就绪?)")?;
247	        stream.set_nodelay(true).ok();
248	        stream
249	            .set_read_timeout(Some(std::time::Duration::from_millis(500)))
250	            .ok();
251	
252	        let mut dummy = [0u8; 1];
253	        match stream.read(&mut dummy) {
254	            Ok(1) => {} // 收到 dummy 字节,连接真实有效
255	            Ok(_) => anyhow::bail!("设备侧 socket 未就绪(EOF)"),
256	            Err(e) => anyhow::bail!("等待 dummy 字节失败: {e}"),
257	        }
258	        stream.set_read_timeout(None).ok();
259	        // 写入看门狗(2026-10-06):设备端 server 若卡住不读(系统繁忙/进程被冻),
260	        // TCP 发送缓冲填满后 `write_all` 会**无限**阻塞 —— 输入全堆在队列里,
261	        // 用户看到的是"延迟暴涨、按键无反应",而通道表面上还"连着",永远不会
262	        // 触发断线路径。给写操作设上限:超时即视为链路故障(与写失败同路),
263	        // 由界面层的自动重连在秒级内把通道拉起来。
264	        stream
265	            .set_write_timeout(Some(std::time::Duration::from_millis(2000)))
266	            .ok();
267	
268	        let connected = Arc::new(AtomicBool::new(true));
269	        let proto_w = Arc::new(AtomicU32::new(screen_w));
270	        let proto_h = Arc::new(AtomicU32::new(screen_h));
271	        let queue = CmdQueue::new();
272	
273	        // 写线程:把控制消息序列化后写入 socket
274	        {
275	            let connected = connected.clone();
276	            let proto_w = proto_w.clone();
277	            let proto_h = proto_h.clone();
278	            let queue = queue.clone();
279	            let mut stream = stream.try_clone()?;
280	            std::thread::spawn(move || {
281	                // 输入链最后一跳:只在有待发指令时运行(其余时间阻塞在队列上),
282	                // 提到最高优先级,保证写完 socket 不被满载的游戏线程挤后。
283	                crate::priority::boost(crate::priority::Class::Highest);
284	                while let Some(cmd) = queue.pop() {
285	                    // 攒批(2026-10-06 延迟修复):一次唤醒把队列里**已经排好**的
286	                    // 命令合成一次 `write_all`。一条一写在 Nagle 已关的连接上等于
287	                    // 一个 TCP 报文 + 一次系统调用;投屏开着时这些报文还要和视频流
288	                    // 一起挤 adbd 的转发,报文数就是排队延迟。攒批不改变顺序
289	                    // (FIFO 原样拼接),也不增加延迟:队列里没有第二条时行为与
290	                    // 旧实现逐字相同。
291	                    //
292	                    // 宽高**每条各读一次**(旧实现就是逐条读的):批里可能夹着
293	                    // `set_screen`(转屏/截图校正),用批次开头那一份会把之后的
294	                    // 命令按旧坐标空间换算 —— 服务端启用视频/`--new-display` 时
295	                    // `PositionMapper` 会因此把它们缩放错位。
296	                    let mut buf = serialize(
297	                        cmd,
298	                        proto_w.load(Ordering::Relaxed) as u16,
299	                        proto_h.load(Ordering::Relaxed) as u16,
300	                    );
301	                    let mut n = 1usize;
302	                    while n < WRITE_BATCH_LIMIT {
303	                        let Some(more) = queue.try_pop() else { break };
304	                        buf.extend_from_slice(&serialize(
305	                            more,
306	                            proto_w.load(Ordering::Relaxed) as u16,
307	                            proto_h.load(Ordering::Relaxed) as u16,
308	                        ));
309	                        n += 1;
310	                    }
311	                    let res = stream.write_all(&buf);
312	                    // 这一批无论结果如何都已离开本地(写成功或随失败丢弃),
313	                    // 先冲销在途量再处理错误 —— 否则失败路径会把在途量漏掉。
314	                    queue.written(n);
315	                    if let Err(e) = res {
316	                        connected.store(false, Ordering::Relaxed);
317	                        // 写入失败是最容易被忽略的故障:命令全部静默丢弃,
318	                        // 用户只看到"按键没反应"。把 errno 留下来。
319	                        diag_warn!(
320	                            "control",
321	                            "控制通道写入失败: {e} (errno {:?}) —— 后续注入命令将全部丢弃",
322	                            e.raw_os_error()
323	                        );
324	                        break;
325	                    }
326	                }
327	            });
328	        }
329	
330	        // 读线程:丢弃服务端下行消息(剪贴板等),避免接收缓冲阻塞
331	        {
332	            let connected = connected.clone();
333	            let mut stream = stream;
334	            std::thread::spawn(move || {
335	                let mut buf = [0u8; 4096];
336	                loop {
337	                    match stream.read(&mut buf) {
338	                        Ok(0) => {
339	                            connected.store(false, Ordering::Relaxed);
340	                            diag_warn!("control", "控制通道对端关闭(EOF),连接标记为断开");
341	                            break;
342	                        }
343	                        Err(e) => {
344	                            connected.store(false, Ordering::Relaxed);
345	                            diag_warn!(
346	                                "control",
347	                                "控制通道读取失败: {e} (errno {:?}),连接标记为断开",
348	                                e.raw_os_error()
349	                            );
350	                            break;
351	                        }
352	                        Ok(_) => {}
353	                    }
354	                }
355	            });
356	        }
357	
358	        diag_info!(
359	            "control",
360	            "控制通道已建立: 端口 {port},坐标空间 {screen_w}x{screen_h}"
361	        );
362	        Ok(Self {
363	            queue,
364	            connected,
365	            screen_w,
366	            screen_h,
367	            proto_w,
368	            proto_h,
369	        })
370	    }
371	
372	    /// 队列深度快照(W1-3,诊断面板显示用)
373	    pub fn queue_stats(&self) -> QueueStats {
374	        self.queue.stats()
375	    }
376	
377	    pub fn is_connected(&self) -> bool {
378	        self.connected.load(Ordering::Relaxed)
379	    }
380	
381	    /// 更新触摸坐标空间。
382	    ///
383	    /// 必须走这个方法而不是直接写 `screen_w/h`:后者改不到写线程手里的值,
384	    /// 会造成"引擎按新尺寸算坐标、协议里声明旧尺寸"的不一致(见字段注释)。
385	    pub fn set_screen(&mut self, w: u32, h: u32) {
386	        self.screen_w = w;
387	        self.screen_h = h;
388	        self.proto_w.store(w, Ordering::Relaxed);
389	        self.proto_h.store(h, Ordering::Relaxed);
390	    }
391	
392	    pub fn send(&self, cmd: ControlCmd) {
393	        self.queue.push(cmd);
394	    }
395	
