489	fn serialize(cmd: ControlCmd, w: u16, h: u16) -> Vec<u8> {
490	    match cmd {
491	        ControlCmd::Touch {
492	            action,
493	            pointer_id,
494	            x,
495	            y,
496	        } => {
497	            let mut buf = [0u8; 32];
498	            buf[0] = TYPE_INJECT_TOUCH;
499	            buf[1] = action;
500	            buf[2..10].copy_from_slice(&pointer_id.to_be_bytes());
501	            // 坐标是协议里的 u32;负值(例如配置允许的超屏坐标)按 0 处理,
502	            // 否则 i32 -> u32 的负数转换会变成一个巨大的值,反而更容易触发服务端异常。
503	            buf[10..14].copy_from_slice(&(x.max(0) as u32).to_be_bytes());
504	            buf[14..18].copy_from_slice(&(y.max(0) as u32).to_be_bytes());
505	            buf[18..20].copy_from_slice(&w.to_be_bytes());
506	            buf[20..22].copy_from_slice(&h.to_be_bytes());
507	            let pressure: u16 = if action == ACTION_UP { 0 } else { 0xFFFF };
508	            buf[22..24].copy_from_slice(&pressure.to_be_bytes());
509	            // action_button(24..28) 与 buttons(28..32) 对触摸恒为 0
510	            buf.to_vec()
511	        }
512	        ControlCmd::Key { action, keycode } => {
513	            let mut buf = [0u8; 14];
514	            buf[0] = TYPE_INJECT_KEYCODE;
515	            buf[1] = action;
516	            buf[2..6].copy_from_slice(&keycode.to_be_bytes());
517	            // repeat(6..10) 与 metastate(10..14) 为 0
518	            buf.to_vec()
519	        }
520	        ControlCmd::UhidCreate {
521	            id,
522	            vendor_id,
523	            product_id,
524	            name,
525	            report_desc,
526	        } => {
527	            let name_bytes = name.as_bytes();
528	            let name_len = name_bytes.len().min(127);
529	            let desc_len = report_desc.len().min(u16::MAX as usize);
530	            let mut buf = Vec::with_capacity(7 + 1 + name_len + 2 + desc_len);
531	            buf.push(TYPE_UHID_CREATE);
532	            buf.extend_from_slice(&id.to_be_bytes());
533	            buf.extend_from_slice(&vendor_id.to_be_bytes());
534	            buf.extend_from_slice(&product_id.to_be_bytes());
535	            buf.push(name_len as u8);
536	            buf.extend_from_slice(&name_bytes[..name_len]);
537	            buf.extend_from_slice(&(desc_len as u16).to_be_bytes());
538	            buf.extend_from_slice(&report_desc[..desc_len]);
539	            buf
540	        }
541	        ControlCmd::UhidInput { id, data } => {
542	            let size = data.len().min(u16::MAX as usize);
543	            let mut buf = Vec::with_capacity(5 + size);
544	            buf.push(TYPE_UHID_INPUT);
545	            buf.extend_from_slice(&id.to_be_bytes());
546	            buf.extend_from_slice(&(size as u16).to_be_bytes());
547	            buf.extend_from_slice(&data[..size]);
548	            buf
549	        }
550	        ControlCmd::UhidDestroy { id } => {
551	            let mut buf = Vec::with_capacity(3);
552	            buf.push(TYPE_UHID_DESTROY);
553	            buf.extend_from_slice(&id.to_be_bytes());
554	            buf
555	        }
556	    }
557	}
