751	/// 把"普通绑定"的实际按下状态对齐到物理按键状态。
752	///
753	/// 这是"归属切换"这条铁律的落地点:凡是会让某个物理键改换门庭的操作
754	/// (临时轮盘启用/停用、总开关切换、配置被编辑),都要在之后调用它。
755	///
756	/// 只对**状态型**动作对账:
757	///   * `Hold`      —— 按着就该有触点,松开就该抬起;
758	///   * `AndroidKey`—— 同上(系统键也要成对);
759	///   * `Tap`(duration=0)是"按一下翻一次"的开关、`Tap`(duration>0)与 `Swipe`
760	///     是一次性动作,都由事件自己收尾 —— 在这里对账会把它们反复翻转/重放。
761	///
762	/// 归属给某个生效中的轮盘方向键、或临时轮盘启用键的物理键不参与普通绑定
763	/// (与事件路径的优先级链完全一致:总开关键 > 启用键 > 轮盘方向键 > 普通绑定)。
764	fn reconcile_binds(
765	    ctl: &ControlClient,
766	    m: &Mapper,
767	    profile: &Profile,
768	    wheels: &[WheelState],
769	    fps_running: bool,
770	    aim_pointers: usize,
771	    held: &Held,
772	    fingers: &mut Fingers,
773	    active_android_keys: &mut HashSet<u16>,
774	    live: &mut EngineLive,
775	) {
776	    // 轮盘与瞄准占用的触点(普通绑定自己不占;对账期间它们不变)
777	    let reserved = wheel_pointers(wheels) + aim_pointers;
778	    for (idx, bind) in profile.binds.iter().enumerate() {
779	        if bind.fps_only {
780	            continue;
781	        }
782	        let want = held.has(bind.key)
783	            && !key_owned_by_wheel(profile, wheels, bind.key)
784	            && !key_owned_by_fps(profile, fps_running, bind.key);
785	        match &bind.action {
786	            Action::Hold { x, y, .. } => {
787	                let pid = bind_pid(idx);
788	                let (px, py) = m.point(*x, *y);
789	                if want {
790	                    if !fingers.is_down(idx) {
791	                        if fingers.try_down(idx, reserved) {
792	                            ctl.touch_down(pid, px, py);
793	                        } else {
794	                            refuse(live, bind.key, RefuseReason::PoolFull);
795	                        }
796	                    }
797	                } else if fingers.release(idx) {
798	                    ctl.touch_up(pid, px, py);
799	                }
800	            }
801	            Action::AndroidKey { keycode } => {
802	                let kc = *keycode as u16;
803	                if want {
804	                    if active_android_keys.insert(kc) {
805	                        ctl.key(true, *keycode);
806	                    }
807	                } else if active_android_keys.remove(&kc) {
808	                    ctl.key(false, *keycode);
809	                }
810	            }
811	            _ => {}
812	        }
813	    }
814	}
