816	/// 把轮盘方向状态对齐到物理按键状态(与 [`reconcile_binds`] 同理)。
817	///
818	/// 方向状态完全由"该轮盘此刻是否生效 × 对应物理键是否按着"决定,于是:
819	///   * 启用临时摇杆的瞬间,已按着的方向键立刻推动摇杆(而不是要重按一次);
820	///   * 停用/配置变化/切总开关时,不再生效的方向一定被抬起来;
821	///   * 不会出现"某个方向永远以为自己被按着"。
822	///
823	/// `extra_pointers` 是普通绑定 + 瞄准此刻占用的触点数(它们与轮盘抢同一个池子)。
824	fn reconcile_wheels(
825	    ctl: &ControlClient,
826	    m: &Mapper,
827	    profile: &Profile,
828	    wheels: &mut [WheelState],
829	    held: &Held,
830	    extra_pointers: usize,
831	    live: &mut EngineLive,
832	) {
833	    for (j, w) in profile.wheels.iter().enumerate() {
834	        if j >= wheels.len() {
835	            break;
836	        }
837	        let engaged = w.temp.is_none() || wheels[j].active;
838	        // R1:临时摇杆(启用中)对该键位有抢占优先级 —— 被抢走的键位上永久轮盘
839	        // 视为"没按下",于是它会立刻回中/抬指(状态是推出来的,不是攒出来的)。
840	        // 自己就是临时轮盘时不看这条(临时 vs 临时 = 一起响应,旧行为)。
841	        if w.kind == WheelKind::Standard {
842	            for (d, key) in [w.up, w.down, w.left, w.right].iter().enumerate() {
843	                let want = wheel_dir_wanted(profile, wheels, w.temp.is_some(), engaged, key, held);
844	                if want && !wheels[j].pressed[d] {
845	                    wheels[j].next_seq = wheels[j].next_seq.wrapping_add(1);
846	                    wheels[j].press_seq[d] = wheels[j].next_seq;
847	                }
848	                wheels[j].pressed[d] = want;
849	            }
850	        } else {
851	            for (d, (_, key)) in w.active_dirs().iter().take(8).enumerate() {
852	                let want = wheel_dir_wanted(profile, wheels, w.temp.is_some(), engaged, key, held);
853	                if want && !wheels[j].custom_pressed[d] {
854	                    wheels[j].next_seq = wheels[j].next_seq.wrapping_add(1);
855	                    wheels[j].custom_seq[d] = wheels[j].next_seq;
856	                }
857	                wheels[j].custom_pressed[d] = want;
858	            }
859	        }
860	        // 本轮盘此刻若已经按着,update_wheel 不会再去申请新触点,故不必减掉自己
861	        let reserved = extra_pointers + wheel_pointers(wheels);
862	        if update_wheel(ctl, m, j, w, &mut wheels[j], reserved) {
863	            // 上报"是哪个方向键按不下"用的代表码(空方向键集合退回 0,只影响日志文字)
864	            let rep = w.up.first().copied().unwrap_or(0);
865	            refuse(live, rep, RefuseReason::PoolFull);
866	        }
867	    }
868	}
