870	/// 该物理键此刻是否归摇杆(生效中的轮盘方向键,或任意临时轮盘的启用键)。
871	///
872	/// 临时轮盘的启用键**无论是否生效**都归它自己:事件路径上它总是被消费掉
873	/// (见 run() 里的启用键分支),所以普通绑定永远收不到它。
874	/// 重连后把"长按型临时轮盘"的启用状态从物理镜像重新推导。
875	///
876	/// 断线清场会把 `active` 一并清零,而启用键(E/Q 这类)的按下事件早在断线前
877	/// 就送完了 —— 如果用户断线期间一直按着它,只清不推的话轮盘会保持"未启用",
878	/// 方向键全被普通绑定接走,要松手重按才恢复。长按型(Hold)的语义就是
879	/// "按住=启用",可以从 [`Held`] 直接推导;切换型(Toggle)是锁存语义,无从
880	/// 推导,保持清零(用户再按一次启用键即可)。
881	fn rederive_hold_temp_wheels(profile: &Profile, held: &Held, wheels: &mut [WheelState]) {
882	    for (j, w) in profile.wheels.iter().enumerate() {
883	        if j >= wheels.len() {
884	            break;
885	        }
886	        if let Some(t) = &w.temp {
887	            if t.mode == TempMode::Hold {
888	                // 组合键启用键:整个集合都按着才算启用(与 `key_set_down` 同口径)。
889	                wheels[j].active = t.key.all_held_by(|k| held.has(k));
890	            }
891	        }
892	    }
893	}
