895	fn key_owned_by_wheel(profile: &Profile, wheels: &[WheelState], code: u16) -> bool {
896	    profile.wheels.iter().enumerate().any(|(j, w)| {
897	        if let Some(t) = &w.temp {
898	            // 组合键启用键按**成员**判定:它任一成员按键都不能走普通绑定。
899	            if t.key.contains(&code) {
900	                return true;
901	            }
902	        }
903	        let engaged = w.temp.is_none() || wheels.get(j).map(|s| s.active).unwrap_or(false);
904	        engaged && w.owns_key(code)
905	    })
906	}
