939	///   * **按下**= 整个集合此刻都按着(`all_held_by`;空集合恒为 false —— 未绑定的方向永不触发);
940	///   * **被抢占**= 集合里**任一成员**落在某个已启用临时轮盘的键位里 ——
941	///     单键配置下与旧口径逐字一致,组合键下只要有一个成员被临时轮盘占走就让位。
942	fn wheel_dir_wanted(
943	    profile: &Profile,
944	    wheels: &[WheelState],
945	    is_temp: bool,
946	    engaged: bool,
947	    keys: &KeySet,
948	    held: &Held,
949	) -> bool {
950	    let down = keys.all_held_by(|k| held.has(k));
951	    let taken = keys
952	        .iter()
953	        .any(|k| key_taken_by_active_temp_wheel(profile, wheels, *k));
954	    engaged && down && (is_temp || !taken)
955	}
