6510	/// 轮盘保活周期(见 [`wheel_keepalive`])。
6511	///
6512	/// 取值权衡:越短,"丢失的那一条落点"恢复越快;越长,往设备端多发的心跳越少。
6513	/// 100ms 意味着一次丢失最多被感知成"0.1 秒没推动",而代价只是每个按着的轮盘
6514	/// 每秒 10 条 Move —— 相对瞄准动辄每秒上千条,可以忽略。
6515	const WHEEL_KEEPALIVE: Duration = Duration::from_millis(100);
6516	
6517	/// 轮盘保活:**按着的轮盘周期性重发当前落点**,顺带补"没按下去"的缺口。
6518	///
6519	/// 为什么必须有:标准轮盘只在"目标点变化"时发 Move,而且发出去就记成已送达
6520	/// (`st.last` 是乐观写入,设备端没有回执)。链路上任何一环把那条 Move 丢掉
6521	/// —— 控制队列丢旧保新、写失败、设备端合并 —— 手指就永远停在原地:因为
6522	/// `touch_down` 先落在**圆心**(见 `update_wheel`),表现正是"轮盘明明按下去了,
6523	/// 按压点却停在原地";若圆心与游戏自身摇杆中心有偏差,游戏读到的就是恒定偏移
6524	/// ——"像被一个中心拽着往某个方向偏"。同理,按下后那条 move 丢失会让方向卡在
6525	/// 旧的一侧,直到下次方向变化才恢复。
6526	///
6527	/// MOVE 是**绝对坐标**语义,重发同一位置对设备与游戏都是幂等的(不产生任何
6528	/// 多余动作),所以这种"无脑重发"是安全的;它把上面那类丢失的恢复时间从
6529	/// "直到下次换方向"(可能永远)压到 0.1 秒。
6530	///
6531	/// 另一条缺口:方向键还按着但 `down == false`(按下被触点池拒了、或那条 down
6532	/// 丢了)。旧实现只等"下一次方向变化"才重试,用户看到的是"推了没反应";
6533	/// 这里直接重跑一次 `update_wheel`,让它按当前方向重新申请按下。
6534	fn wheel_keepalive(
6535	    ctl: &ControlClient,
6536	    m: &Mapper,
6537	    profile: &Profile,
6538	    wheels: &mut [WheelState],
6539	    extra_pointers: usize,
6540	) {
6541	    let now = Instant::now();
6542	    for j in 0..profile.wheels.len().min(wheels.len()) {
6543	        let w = &profile.wheels[j];
6544	        if w.kind == WheelKind::Execute {
6545	            // 执行轮盘是一次性手势:按下时就排好了整段插值 + 抬手,没有"按着"的状态
6546	            continue;
6547	        }
6548	        if wheels[j].down {
6549	            if !keepalive_due(wheels[j].sent_at, now) {
6550	                continue;
6551	            }
6552	            let (x, y) = wheels[j].last;
6553	            ctl.touch_move(wheel_pid(j), x, y);
6554	            wheels[j].sent_at = Some(now);
6555	            continue;
6556	        }
6557	        let wanted = if w.kind == WheelKind::Standard {
6558	            wheels[j].pressed.iter().any(|p| *p)
6559	        } else {
6560	            wheels[j].custom_pressed.iter().any(|p| *p)
6561	        };
6562	        // 重试也要有节拍:触点池满时 update_wheel 什么都不发,不节流就会变成
6563	        // 每轮(4ms)一次空转。`sent_at` 在这里的含义是"上次尝试的时刻"。
6564	        if !wanted || !keepalive_due(wheels[j].sent_at, now) {
6565	            continue;
6566	        }
6567	        // 触点预算每次现算:这一轮里前面的轮盘可能刚补上按下。
6568	        let reserved = extra_pointers + wheel_pointers(wheels);
6569	        // 返回的"池满"在这里**故意不上报**:事件路径与 `reconcile_wheels` 已经
6570	        // 报过一次,每 100ms 重报一次只会刷屏(这里也拿不到 `live`)。
6571	        let _ = update_wheel(ctl, m, j, w, &mut wheels[j], reserved);
6572	        wheels[j].sent_at = Some(now);
6573	    }
6574	}
