14641	/// 纵横比相对偏差超过它就地"未对齐"(方案 W2-2 定 2%)。
14642	const SPACE_ASPECT_TOLERANCE: f32 = 0.02;
14643	
14644	/// 截图空间与控制通道(注入)空间纵横比不一致的证据(W2-2 守卫,判定见
14645	/// [`space_mismatch`])。
14646	#[derive(Debug, Clone, Copy, PartialEq)]
14647	struct SpaceMismatch {
14648	    /// 截图尺寸(浮层绘制与取点所依据的空间)
14649	    shot: (u32, u32),
14650	    /// 控制通道尺寸(引擎注入所用坐标空间)
14651	    inject: (u32, u32),
14652	    /// 纵横比相对偏差(0.05 = 5%,两方向归一:谁大谁做分子)
14653	    dev: f32,
14654	}
