14659	        let (sw, sh) = self.shot;
14660	        let (iw, ih) = self.inject;
14661	        format!(
14662	            "截图 {sw}x{sh} 与触摸坐标空间 {iw}x{ih} 的纵横比不一致(偏差 {:.0}%)",
