132	fn parse_refresh_rate_latency(text: &str) -> Option<f32> {
133	    let first = text
134	        .lines()
135	        .find_map(|line| line.trim().parse::<f64>().ok());
136	    if let Some(period) = first {
137	        if (1_000.0..=100_000_000.0).contains(&period) {
138	            let fps = 1_000_000_000.0 / period;
139	            if (1.0..=1000.0).contains(&fps) {
140	                return Some(fps as f32);
141	            }
142	        }
143	    }
144	    let timestamps: Vec<u64> = text
145	        .lines()
146	        .filter_map(|line| line.split(',').next()?.trim().parse().ok())
147	        .filter(|v: &u64| *v > 1_000_000)
148	        .collect();
149	    if timestamps.len() >= 2 {
150	        let first = timestamps[0];
151	        let last = *timestamps.last().unwrap();
152	        if last > first {
153	            let fps = (timestamps.len() - 1) as f64 * 1_000_000_000.0 / (last - first) as f64;
154	            if (1.0..=1000.0).contains(&fps) {
155	                return Some(fps as f32);
156	            }
157	        }
158	    }
159	    None
160	}
