162	fn parse_refresh_rate_text(text: &str) -> Option<f32> {
163	    for key in ["refreshRate=", "fps="] {
164	        if let Some(value) = parse_float_after(text, key) {
165	            if (1.0..=1000.0).contains(&value) {
166	                return Some(value as f32);
167	            }
168	        }
169	    }
170	    None
171	}
