173	fn parse_float_after(text: &str, key: &str) -> Option<f32> {
174	    let start = text.find(key)? + key.len();
175	    let rest = text[start..].trim_start();
176	    let end = rest
177	        .find(|c: char| !(c.is_ascii_digit() || c == '.' || c == '-'))
178	        .unwrap_or(rest.len());
179	    rest[..end].parse().ok()
180	}
