640	    fn drop(&mut self) {
641	        // 退出清理必须是有界的：kill 后只轮询 try_wait，绝不无条件 wait。
642	        let deadline = Instant::now() + Duration::from_millis(800);
643	        let _ = self.child.kill();
644	        while Instant::now() < deadline {
645	            match self.child.try_wait() {
646	                Ok(Some(_)) => break,
647	                Ok(None) => std::thread::sleep(Duration::from_millis(10)),
648	                Err(_) => break,
649	            }
650	        }
651	        // adb forward 清理同样设置超时，避免 adb server 异常时把 GUI 退出卡住。
652	        if let Ok(mut child) = adb_cmd(Some(&self.serial))
653	            .args(["forward", "--remove", &format!("tcp:{}", self.port)])
654	            .stdout(Stdio::null())
655	            .stderr(Stdio::null())
656	            .spawn()
657	        {
658	            let deadline = Instant::now() + Duration::from_millis(600);
659	            while Instant::now() < deadline {
660	                match child.try_wait() {
661	                    Ok(Some(_)) => break,
662	                    Ok(None) => std::thread::sleep(Duration::from_millis(10)),
663	                    Err(_) => break,
664	                }
665	            }
666	            if child.try_wait().ok().flatten().is_none() {
667	                let _ = child.kill();
668	            }
669	        }
670	    }
