673	fn split_args(input: &str) -> Vec<String> {
674	    let mut result = Vec::new();
675	    let mut current = String::new();
676	    let mut quote = None;
677	    let mut escaped = false;
678	    for ch in input.chars() {
679	        if escaped {
680	            current.push(ch);
681	            escaped = false;
682	            continue;
683	        }
684	        if ch == '\\' && quote != Some('\'') {
685	            escaped = true;
686	            continue;
687	        }
688	        if let Some(q) = quote {
689	            if ch == q {
690	                quote = None;
691	            } else {
692	                current.push(ch);
693	            }
694	            continue;
695	        }
696	        if ch == '\'' || ch == '"' {
697	            quote = Some(ch);
698	        } else if ch.is_whitespace() {
699	            if !current.is_empty() {
700	                result.push(std::mem::take(&mut current));
701	            }
702	        } else {
703	            current.push(ch);
704	        }
705	    }
706	    if escaped {
707	        current.push('\\');
708	    }
709	    if !current.is_empty() {
710	        result.push(current);
711	    }
712	    result
713	}
