715	/// 从 scrcpy 的一行输出里解析 `--print-fps` 的帧率 —— 投屏流的**真实**帧率。
716	///
717	/// scrcpy 的 FPS 计数器每秒打印一行,格式(见 scrcpy 源码 `run_fps_counter`):
718	/// `%u fps` 或 `%u fps (+%u frames skipped)`;经 scrcpy 的日志器会带上
719	/// `INFO: ` 前缀,再经本程序日志通道转发时又会加 `scrcpy stdout: ` 前缀,
720	/// 所以两种前缀都剥掉。只认"数字 + fps(+ 可选括号说明)"的干净行,避免把
721	/// 别的含 " fps" 的字串(参数回显之类)误吃进来。
722	pub(crate) fn parse_scrcpy_fps(line: &str) -> Option<f32> {
723	    let t = line.trim();
724	    let t = t.strip_prefix("scrcpy stdout: ").unwrap_or(t).trim_start();
725	    let t = t
726	        .strip_prefix("INFO: ")
727	        .or_else(|| t.strip_prefix("DEBUG: "))
728	        .unwrap_or(t);
729	    let (num, rest) = t.split_once(" fps")?;
730	    let v: f32 = num.trim().parse().ok()?;
731	    let rest = rest.trim();
732	    if !(rest.is_empty() || rest.starts_with('(')) {
733	        return None;
734	    }
735	    // 0 是计数器停摆的占位;"每小时几十万帧"不可能是真实读数,当解析失败
736	    (v > 0.0 && v <= 1000.0).then_some(v)
737	}
