4591	fn point_at_progress(points: &[(i32, i32)], progress: f32) -> (i32, i32) {
4592	    if points.is_empty() {
4593	        return (0, 0);
4594	    }
4595	    if points.len() == 1 {
4596	        return points[0];
4597	    }
4598	    let seg_len = |i: usize| -> f32 {
4599	        let (x0, y0) = points[i];
4600	        let (x1, y1) = points[i + 1];
4601	        ((x1 - x0) as f32).hypot((y1 - y0) as f32)
