4603	    let total: f32 = (0..points.len() - 1).map(seg_len).sum();
4604	    if total <= 1e-6 {
4605	        return points[0];
4606	    }
4607	    let target = progress.clamp(0.0, 1.0) * total;
4608	    let mut acc = 0.0f32;
